import limited_client as r, numpy as np
from scipy.ndimage import label
for cam in ['corner3','topview']:
 o=r.observe(cam); im=o['rgb']; dep=o['depth_m'];
 # find red components small and z below .1 via world calc
 m=(im[:,:,0]>100)&(im[:,:,0]>im[:,:,1]*1.35)&(im[:,:,0]>im[:,:,2]*1.3); lab,n=label(m); out=[]
 K=o['intrinsic'];T=o['camera_to_world']
 for i in range(1,n+1):
  y,x=np.where(lab==i)
  if len(x)>100 and len(x)<1500:
   u=x.mean();v=y.mean();d=np.median(dep[y,x]); p=np.array([(u-K[0,2])*d/K[0,0],(v-K[1,2])*d/K[1,1],d,1]); w=T@p
   if w[2]<.15: out.append((len(x),round(u,1),round(v,1),np.round(w[:3],3).tolist()))
 print(cam,out)
 print('tcp',o['robot']['tcp_position'])
